package main

import (
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
)

// ErrorNotification/TurnError fields verified against the schema generated by
// Codex 0.162.1. Unknown error variants remain compatible with older/newer CLIs.
type codexTurnError struct {
	Message           string          `json:"message"`
	CodexErrorInfo    json.RawMessage `json:"codexErrorInfo"`
	AdditionalDetails *string         `json:"additionalDetails"`
}

const codexRetryMaxCauses = 6

// Store only a bounded set of public classifications, never the native detail
// body, which may contain request contents, URLs, headers or credentials.
type codexRetryDiagnostics struct {
	causes []string
}

var codexRetryHTTPStatus = regexp.MustCompile(`(?i)\b(?:HTTP(?:\s+status)?|status(?:\s+code)?)[\s:=]+(429|502|503|504)\b|\b429\s+Too Many Requests\b`)

func codexErrorClassification(e codexTurnError) (causes []string, streamFailure bool) {
	add := func(value string) {
		for _, prior := range causes {
			if prior == value {
				return
			}
		}
		if len(causes) < codexRetryMaxCauses {
			causes = append(causes, value)
		}
	}
	if len(e.CodexErrorInfo) <= 8192 {
		var code string
		if json.Unmarshal(e.CodexErrorInfo, &code) == nil {
			switch code {
			case "serverOverloaded":
				add("服务繁忙")
			case "rateLimitExceeded":
				add("请求受到限流")
			case "usageLimitExceeded":
				add("账号额度已达上限")
			case "contextWindowExceeded":
				add("上下文超出窗口")
			}
		} else {
			var variants map[string]json.RawMessage
			if json.Unmarshal(e.CodexErrorInfo, &variants) == nil {
				for _, name := range []string{"httpConnectionFailed", "responseStreamConnectionFailed", "responseStreamDisconnected", "responseTooManyFailedAttempts"} {
					raw, exists := variants[name]
					if !exists {
						continue
					}
					streamFailure = streamFailure || name != "httpConnectionFailed"
					var detail struct {
						Status *int `json:"httpStatusCode"`
					}
					if json.Unmarshal(raw, &detail) == nil && detail.Status != nil && *detail.Status >= 400 && *detail.Status <= 599 {
						add(fmt.Sprintf("上游返回 HTTP %d", *detail.Status))
					}
				}
			}
		}
	}
	// Additional details are inspected only for these known public signals.
	// Never expose a raw substring or parse arbitrary nested request data.
	texts := []string{e.Message}
	if e.AdditionalDetails != nil {
		texts = append(texts, *e.AdditionalDetails)
	}
	for _, text := range texts {
		if len(text) > 16384 {
			text = text[:16384]
		}
		lower := strings.ToLower(text)
		if strings.Contains(lower, "high demand") || strings.Contains(lower, "highdemanderror") || strings.Contains(lower, "server overloaded") {
			add("服务繁忙")
		}
		for _, match := range codexRetryHTTPStatus.FindAllStringSubmatch(text, 4) {
			status := match[1]
			if status == "" {
				status = "429"
			}
			add("上游返回 HTTP " + status)
		}
	}
	message := strings.ToLower(e.Message)
	streamFailure = streamFailure || strings.Contains(message, "stream disconnected") || strings.Contains(message, "stream closed") || strings.Contains(message, "exceeded retry limit")
	return causes, streamFailure
}

func (d *codexRetryDiagnostics) progress(e codexTurnError, redact func(string) string) string {
	causes, _ := codexErrorClassification(e)
	for _, cause := range causes {
		seen := false
		for _, prior := range d.causes {
			seen = seen || prior == cause
		}
		if !seen && len(d.causes) < codexRetryMaxCauses {
			d.causes = append(d.causes, cause)
		}
	}
	message := strings.TrimSpace(redact(e.Message))
	if len(message) > 4096 {
		message = string([]rune(message)[:min(len([]rune(message)), 1024)]) + "…"
	}
	if message == "" {
		message = "请求暂未完成"
	}
	if len(causes) > 0 {
		message += "（" + strings.Join(causes, "；") + "）"
	}
	return "Codex 正在重试：" + message
}

func (d *codexRetryDiagnostics) failure(e *codexTurnError, redact func(string) string) string {
	message := "Codex 原生轮次失败"
	if e == nil {
		return message
	}
	if e.Message != "" {
		message += "：" + redact(e.Message)
	}
	_, streamFailure := codexErrorClassification(*e)
	if streamFailure && len(d.causes) > 0 {
		message += "；本轮原生重试曾报告：" + strings.Join(d.causes, "；")
	}
	return message
}
